$module=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/OrderAdminModule.php');$app=(string)file_get_contents($root.'/server/app/Application/Order/WebAdminOrder.php');$contract=(string)file_get_contents($root.'/server/app/Contracts/AdminOrderRepository.php');$read=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminOrderReadStore.php');$write=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminOrderWriteStore.php');$workflow=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminOrderWorkflowStore.php');$media=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminOrderMediaStore.php');$facade=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminOrderRepository.php');$kernel=(string)file_get_contents($root.'/server/app/Http/Admin/AdminKernel.php');$legacy=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/LegacyAdminModule.php');
$routes=['orders','orders.create','orders.view','orders.update','orders.audit','orders.publish','orders.cancel','orders.quote','orders.assign','orders.invite','orders.invite.revoke','orders.release','orders.media.upload','orders.media.delete','media.view'];foreach($routes as $route){$assert(strpos($module,"'{$route}'")!==false,'formal module missing '.$route);$assert(strpos($legacy,"'{$route}'")!==false,'anti-fallback missing '.$route);}
$assert(strpos($kernel,'new OrderAdminModule($db,$auth,$csrf)')!==false,'AdminKernel did not register OrderAdminModule');$assert(strpos($module,'SELECT ')===false&&strpos($module,'UPDATE ')===false&&strpos($module,'INSERT ')===false&&strpos($module,'DELETE ')===false,'Order Http module contains SQL');$assert(strpos($module,'WorkerAdmin\\Controllers\\')===false&&strpos($module,'WorkerAdmin\\Services\\')===false&&strpos($module,'WorkerAdmin\\Infrastructure\\')===false,'Order Http bypasses Application boundary');$assert(strpos($app,'WorkerAdmin\\Infrastructure\\')===false&&strpos($app,'WorkerAdmin\\Services\\')===false,'Order Application depends on implementation layer');$assert(strpos($contract,'WorkerAdmin\\Infrastructure\\')===false&&strpos($contract,'WorkerAdmin\\Services\\')===false,'Order contract depends on implementation layer');$assert(strpos($read,"o.is_demo=0 AND o.public_no NOT LIKE 'WO-DEMO-%'")!==false,'order list/detail lost demo isolation');$assert(strpos($read,'decrypt_private_value')!==false,'admin order private-field decryption lost');$assert(strpos($write,"relation_type='measurement_construction'")!==false,'measurement-construction worker/publication guard lost');$assert(strpos($write,'amount_cents_snapshot')!==false&&strpos($write,'booking_fee_cents_snapshot')!==false,'assignment no longer reconciles accepted quote/payment snapshots');$assert(strpos($write,'commission_rate_bp_snapshot')!==false&&strpos($write,'commission_min_cents_snapshot')!==false,'assignment/quote commission snapshots lost');$assert(strpos($workflow,'DatabaseOrderCancellationRiskRepository')!==false&&strpos($workflow,'captureCancellation')!==false,'admin cancel/audit rejection lost cancellation-risk snapshot');$assert(strpos($workflow,"'measurement_balance','measurement_change'")!==false,'measurement refundable payments lost balance/change payments');$assert(strpos($workflow,'foreach($payments as $payment)')!==false&&strpos($workflow,"'pending_review'")!==false,'forced cancellation no longer splits refunds by original payment');$assert(strpos($workflow,"['api_version']")!==false&&strpos($workflow,'WeChatPayService')!==false,'audit rejection refund no longer follows original payment API version');$assert(strpos($workflow,"hash('sha256',$token)")!==false||strpos($workflow,"hash('sha256',\$token)")!==false,'one-time invite hashing lost');$assert(strpos($workflow,'MiniProgramCodeService')!==false,'mini-program invite code generation lost');$assert(strpos($media,'ImageOptimizerService')!==false&&strpos($media,'QiniuStorageService')!==false,'order media optimization/Qiniu path lost');$assert(strpos($media,"'pending_delete'")!==false&&strpos($media,"'/../'")!==false&&strpos($media,'storage/private')!==false,'media refcount/pending-delete or private-path traversal guard lost');$assert(strpos($facade,'DatabaseAdminOrderReadStore')!==false&&strpos($facade,'DatabaseAdminOrderWriteStore')!==false&&strpos($facade,'DatabaseAdminOrderWorkflowStore')!==false&&strpos($facade,'DatabaseAdminOrderMediaStore')!==false,'order persistence facade is not split by responsibility');$assert(!is_file($root.'/server/app/Controllers/AdminController.php'),'retired AdminController was restored');
echo "Admin order migration OK: final 15 Web Admin order routes formally owned; privacy, measurement linkage, quote/payment snapshots, cancellation refunds, invite tokens and private media guards retained; retired AdminController absent.\n";
